import { useDeferredValue, useEffect, useState } from 'react'
import {
  CarFront,
  ChevronLeft,
  DatabaseBackup,
  FileSpreadsheet,
  ChevronRight,
  Filter,
  ImagePlus,
  Plus,
  Search,
  X,
} from 'lucide-react'
import {
  useCreateGarageVehicle,
  useFleetExport,
  useGarageAreas,
  useGarageVehicles,
} from '@features/central-garage/hooks'
import { garageVehicleSchema } from '@features/central-garage/schemas'
import type { GarageArea, GarageShift } from '@features/central-garage/types'
import {
  GARAGE_OWNERSHIP_LABELS,
  GARAGE_VEHICLE_CATEGORY_LABELS,
} from '@features/central-garage/vehicle-details'
import { LoadingSpinner } from '@components/feedback/LoadingSpinner'
import { EmptyState } from '@components/feedback/EmptyState'
import { VehicleCard } from '../components/VehicleCard'
import { FleetImportDialog } from '../components/FleetImportDialog'
import { DriverPicker } from '../components/DriverPicker'
import { ShiftSelect } from '@features/hr-shifts/ShiftSelect'
import { ExternalDriverPicker } from '../components/ExternalDriverPicker'
import { VehicleDriversEditor } from '../components/VehicleDriversEditor'
import { buildDriverSlots, validateExtraDrivers, type ExtraDriverRow } from '@features/central-garage/vehicle-drivers'
import { ExecPageHeader } from '@components/executive/ExecPageHeader'
import { parentSectorTitle, parentCodesOf } from '@features/sectors'

const inputClass =
  'h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm outline-none transition focus:border-cyan-600 focus:ring-2 focus:ring-cyan-100'
const blank = {
  vehicleName: '',
  dbNumber: '',
  plateNumber: '',
  chassisNumber: '',
  vehicleCategory: 'other' as keyof typeof GARAGE_VEHICLE_CATEGORY_LABELS,
  ownershipType: 'owned' as keyof typeof GARAGE_OWNERSHIP_LABELS,
  lessorName: '',
  rentalContractNo: '',
  rentalStartDate: '',
  rentalEndDate: '',
  modelYear: '',
  vehicleColor: '',
  specifications: '',
  driverKind: 'employee' as 'employee' | 'external',
  driverEmployeeId: '',
  driverExternalId: '',
  shift: 'morning' as GarageShift,
  sectorId: '',
  image: null as File | null,
}

export default function VehiclesDatabasePage({
  managementMode = false,
}: {
  managementMode?: boolean
}) {
  const [search, setSearch] = useState('')
  const deferredSearch = useDeferredValue(search)
  const [sectorId, setSectorId] = useState('')
  const [shift, setShift] = useState('')
  const [page, setPage] = useState(1)
  const [open, setOpen] = useState(false)
  const [importOpen, setImportOpen] = useState(false)
  const fleetExport = useFleetExport()
  useEffect(() => setPage(1), [deferredSearch, sectorId, shift])
  const areas = useGarageAreas()
  const vehicles = useGarageVehicles({
    search: deferredSearch,
    sectorId: sectorId ? Number(sectorId) : undefined,
    shift: (shift as GarageShift) || undefined,
    page,
    pageSize: 24,
  })
  const total = vehicles.data?.totalCount ?? 0
  const pages = Math.max(1, Math.ceil(total / 24))
  return (
    <section className="space-y-5" dir="rtl" data-testid="vehicles-database-page">
      <ExecPageHeader icon="database" title="الآليات" subtitle={managementMode ? 'قاعدة بيانات الأسطول — المصدر المركزي لإضافة وتعديل بيانات آليات القاطعين' : 'عرض آليات الكراج المرتبط بحسابك — البيانات الأساسية للقراءة فقط'}
        stats={[{ label: 'إجمالي الآليات', value: total, tone: 'gold' }, { label: 'الصفحات', value: pages }]}
        actions={managementMode ? (<div className="flex flex-wrap gap-2">
            <button
              data-testid="open-add-vehicle"
              onClick={() => setOpen(true)}
              className="inline-flex h-9 items-center gap-1 rounded-xl bg-white px-3 text-xs font-black text-[#0b3d6b] shadow"
            >
              <Plus size={18} />
              إضافة آلية
            </button>
            <button data-testid="fleet-export" onClick={() => fleetExport.mutate(false)} disabled={fleetExport.isPending} className="inline-flex h-9 items-center gap-1 rounded-xl bg-white/10 px-3 text-xs font-black text-white ring-1 ring-white/25 disabled:opacity-50">
              <FileSpreadsheet size={16} />{fleetExport.isPending ? 'جارٍ التصدير…' : 'تصدير Excel'}
            </button>
            <button data-testid="fleet-import-open" onClick={() => setImportOpen(true)} className="inline-flex h-9 items-center gap-1 rounded-xl bg-white/10 px-3 text-xs font-black text-white ring-1 ring-white/25">
              <DatabaseBackup size={16} />استرداد من Excel
            </button>
          </div>) : undefined} />
      <div className="grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:grid-cols-[1fr_220px_180px_auto]">
        <label className="relative">
          <Search className="absolute right-3 top-3 text-slate-400" size={18} />
          <input
            data-testid="vehicle-search"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className={`${inputClass} pr-10`}
            placeholder="DB، السيارة، السائق، اللوحة أو الشاصي"
          />
        </label>
        <select
          data-testid="vehicle-area-filter"
          value={sectorId}
          onChange={(e) => setSectorId(e.target.value)}
          className={inputClass}
        >
          <option value="">كل المواقع</option>
          {/* 00394: القطاعات من بيانات المناطق نفسها */}{parentCodesOf((areas.data ?? [])).map((parent) => <optgroup key={parent} label={parentSectorTitle(parent)}>{(areas.data ?? []).filter((a) => a.parentSector === parent).map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}</optgroup>)}
        </select>
        <ShiftSelect testId="vehicle-shift-filter" value={shift} onChange={setShift} className={inputClass} allLabel="كل الشفتات" />
        <div className="flex items-center justify-center gap-2 rounded-xl bg-slate-50 px-4 text-sm font-bold text-slate-700">
          <Filter size={16} />
          {total} آلية
        </div>
      </div>
      {vehicles.isLoading ? (
        <div className="rounded-2xl bg-white p-12">
          <LoadingSpinner label="جارٍ تحميل الآليات…" />
        </div>
      ) : vehicles.isError ? (
        <div className="rounded-2xl border border-red-200 bg-red-50 p-6 text-center text-sm font-bold text-red-700">
          تعذر تحميل قاعدة بيانات الآليات. حاول مرة أخرى.
        </div>
      ) : (vehicles.data?.rows.length ?? 0) === 0 ? (
        <EmptyState
          title="لا توجد آليات مطابقة"
          hint={
            managementMode
              ? 'غيّر الفلاتر أو أضف آلية جديدة'
              : 'لا توجد آليات ضمن قاطع الكراج المرتبط أو الفلاتر الحالية'
          }
        />
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4">
          {vehicles.data?.rows.map((vehicle) => (
            <VehicleCard
              key={vehicle.id}
              vehicle={vehicle}
              basePath={
                managementMode ? '/ops-room/vehicles-database' : '/central-garage/vehicles-database'
              }
            />
          ))}
        </div>
      )}
      {total > 24 && (
        <nav className="flex items-center justify-center gap-3" aria-label="صفحات الآليات">
          <button
            aria-label="الصفحة السابقة"
            disabled={page === 1}
            onClick={() => setPage((p) => p - 1)}
            className="rounded-xl border bg-white p-2 disabled:opacity-40"
          >
            <ChevronRight />
          </button>
          <span className="text-sm font-bold">
            {page} من {pages}
          </span>
          <button
            aria-label="الصفحة التالية"
            disabled={page >= pages}
            onClick={() => setPage((p) => p + 1)}
            className="rounded-xl border bg-white p-2 disabled:opacity-40"
          >
            <ChevronLeft />
          </button>
        </nav>
      )}
      {managementMode && importOpen && <FleetImportDialog onClose={() => setImportOpen(false)} />}
      {managementMode && open && (
        <AddVehicleDialog areas={areas.data ?? []} onClose={() => setOpen(false)} />
      )}
    </section>
  )
}

function AddVehicleDialog({ areas, onClose }: { areas: GarageArea[]; onClose: () => void }) {
  const [form, setForm] = useState(blank)
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [extraDrivers, setExtraDrivers] = useState<ExtraDriverRow[]>([])
  const [driverErrors, setDriverErrors] = useState<Record<string, string>>({})
  const [preview, setPreview] = useState<string | null>(null)
  const create = useCreateGarageVehicle()
  useEffect(
    () => () => {
      if (preview) URL.revokeObjectURL(preview)
    },
    [preview],
  )
  const update = (key: string, value: string) => {
    setForm((current) => ({ ...current, [key]: value }))
    setErrors((current) => ({ ...current, [key]: '' }))
  }
  const choose = (file: File | null) => {
    if (preview) URL.revokeObjectURL(preview)
    setForm((current) => ({ ...current, image: file }))
    setPreview(file ? URL.createObjectURL(file) : null)
    setErrors((current) => ({ ...current, image: '' }))
  }
  const submit = (event: React.FormEvent) => {
    event.preventDefault()
    const parsed = garageVehicleSchema.safeParse(form)
    // 00377: الصفوف الإضافية تُتحقق مع السائق الأول (الشفت الرئيسي) قبل الإرسال
    const extraErrors = validateExtraDrivers(form, extraDrivers)
    setDriverErrors(extraErrors)
    if (!parsed.success) {
      setErrors(
        Object.fromEntries(
          parsed.error.issues.map((issue) => [String(issue.path[0]), issue.message]),
        ),
      )
      return
    }
    if (Object.keys(extraErrors).length) return
    const drivers = extraDrivers.length ? buildDriverSlots({ ...form, sectorId: parsed.data.sectorId }, extraDrivers) : undefined
    create.mutate({ ...parsed.data, drivers }, { onSuccess: onClose })
  }
  return (
    <div
      className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/60 p-4"
      role="dialog"
      aria-modal="true"
      aria-label="إضافة آلية"
      data-testid="add-vehicle-dialog"
    >
      <form
        onSubmit={submit}
        className="mx-auto my-4 w-full max-w-3xl rounded-3xl bg-white p-5 shadow-2xl sm:p-7"
      >
        <div className="flex justify-between">
          <div>
            <h2 className="text-xl font-black">إضافة آلية جديدة</h2>
            <p className="text-sm text-slate-500">أدخل البيانات الأساسية والإسناد الحالي</p>
          </div>
          <button
            type="button"
            aria-label="إغلاق"
            onClick={onClose}
            className="rounded-xl p-2 hover:bg-slate-100"
          >
            <X />
          </button>
        </div>
        <div className="mt-6 grid gap-4 sm:grid-cols-2">
          <Field label="صورة الآلية" error={errors.image} wide>
            <label className="flex min-h-36 cursor-pointer items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed border-cyan-200 bg-cyan-50/50">
              {preview ? (
                <img src={preview} alt="معاينة الآلية" className="h-44 w-full object-cover" />
              ) : (
                <span className="flex flex-col items-center gap-2 text-sm font-bold text-cyan-800">
                  <ImagePlus />
                  اختر صورة JPG أو PNG أو WebP
                </span>
              )}
              <input
                data-testid="vehicle-image"
                type="file"
                accept="image/jpeg,image/png,image/webp"
                className="sr-only"
                onChange={(e) => choose(e.target.files?.[0] ?? null)}
              />
            </label>
          </Field>
          <Field label="اسم/وصف الآلية" error={errors.vehicleName}>
            <input
              data-testid="vehicle-name"
              className={inputClass}
              value={form.vehicleName}
              onChange={(e) => update('vehicleName', e.target.value)}
              placeholder="مثال: كابسة النفايات رقم 4"
            />
          </Field>
          <Field label="نوع الآلية" error={errors.vehicleCategory}>
            <select
              data-testid="vehicle-category"
              className={inputClass}
              value={form.vehicleCategory}
              onChange={(e) => update('vehicleCategory', e.target.value)}
            >
              {Object.entries(GARAGE_VEHICLE_CATEGORY_LABELS).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </Field>
          <Field label="ملكية الآلية" error={errors.ownershipType}>
            <select
              data-testid="vehicle-ownership"
              className={inputClass}
              value={form.ownershipType}
              onChange={(e) => update('ownershipType', e.target.value)}
            >
              {Object.entries(GARAGE_OWNERSHIP_LABELS).map(([value, label]) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </Field>
          {form.ownershipType === 'rented' && (
            <>
              <Field label="اسم الجهة المؤجرة" error={errors.lessorName}>
                <input
                  data-testid="vehicle-lessor"
                  className={inputClass}
                  value={form.lessorName}
                  onChange={(e) => update('lessorName', e.target.value)}
                />
              </Field>
              <Field label="رقم عقد الإيجار" error={errors.rentalContractNo} optional>
                <input
                  data-testid="vehicle-contract"
                  className={inputClass}
                  value={form.rentalContractNo}
                  onChange={(e) => update('rentalContractNo', e.target.value)}
                />
              </Field>
              <Field label="بداية الإيجار" error={errors.rentalStartDate} optional>
                <input
                  type="date"
                  className={inputClass}
                  value={form.rentalStartDate}
                  onChange={(e) => update('rentalStartDate', e.target.value)}
                />
              </Field>
              <Field label="نهاية الإيجار" error={errors.rentalEndDate} optional>
                <input
                  type="date"
                  min={form.rentalStartDate}
                  className={inputClass}
                  value={form.rentalEndDate}
                  onChange={(e) => update('rentalEndDate', e.target.value)}
                />
              </Field>
            </>
          )}
          <Field label="رقم DB" error={errors.dbNumber}>
            <input
              data-testid="vehicle-db"
              className={inputClass}
              value={form.dbNumber}
              onChange={(e) => update('dbNumber', e.target.value)}
              placeholder="رقم فريد"
            />
          </Field>
          <Field label="رقم اللوحة" error={errors.plateNumber}>
            <input
              data-testid="vehicle-plate"
              className={inputClass}
              value={form.plateNumber}
              onChange={(e) => update('plateNumber', e.target.value)}
            />
          </Field>
          <Field label="رقم الشاصي" error={errors.chassisNumber}>
            <input
              data-testid="vehicle-chassis"
              className={inputClass}
              value={form.chassisNumber}
              onChange={(e) => update('chassisNumber', e.target.value)}
            />
          </Field>
          <Field label="سنة الصنع" error={errors.modelYear} optional>
            <input
              type="number"
              min="1950"
              max={new Date().getFullYear() + 1}
              className={inputClass}
              value={form.modelYear}
              onChange={(e) => update('modelYear', e.target.value)}
            />
          </Field>
          <Field label="اللون" error={errors.vehicleColor} optional>
            <input
              className={inputClass}
              value={form.vehicleColor}
              onChange={(e) => update('vehicleColor', e.target.value)}
            />
          </Field>
          <Field label="مواصفات وملاحظات" error={errors.specifications} wide optional>
            <textarea
              data-testid="vehicle-specifications"
              rows={3}
              className="w-full rounded-xl border p-3 text-sm"
              value={form.specifications}
              onChange={(e) => update('specifications', e.target.value)}
              placeholder="السعة، التجهيزات، الحالة أو أي تفاصيل تشغيلية"
            />
          </Field>
          <div className="space-y-2 rounded-2xl border border-slate-200 p-3 sm:col-span-2" data-testid="vehicle-driver-kind">
            <div className="flex flex-wrap items-center gap-2 text-xs font-bold text-slate-600">
              <span>السائق الأساسي للشفت الرئيسي — نوعه:</span>
              {([['employee', 'موظف (HR)'], ['external', 'سائق متعهد']] as const).map(([k, label]) => (
                <button key={k} type="button" data-testid={`vehicle-driver-kind-${k}`} aria-pressed={form.driverKind === k}
                  className={`rounded-xl px-3 py-1.5 text-xs font-black ${form.driverKind === k ? 'bg-slate-900 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200'}`}
                  onClick={() => setForm((c) => ({ ...c, driverKind: k, driverEmployeeId: '', driverExternalId: '' }))}>{label}</button>
              ))}
            </div>
            {form.driverKind === 'employee' ? (
              <DriverPicker
                testId="vehicle-driver"
                value={form.driverEmployeeId}
                onChange={(id) => update('driverEmployeeId', id)}
                error={errors.driverEmployeeId}
              />
            ) : (
              <ExternalDriverPicker value={form.driverExternalId} onChange={(id) => update('driverExternalId', id)} error={errors.driverExternalId} />
            )}
          </div>
          <VehicleDriversEditor rows={extraDrivers} onChange={(rows) => { setExtraDrivers(rows); setDriverErrors({}) }} mainShift={form.shift} errors={driverErrors} />
          <Field label="الشفت" error={errors.shift}>
            <ShiftSelect testId="vehicle-shift" className={inputClass} value={form.shift} onChange={(v) => update('shift', v)} />
          </Field>
          <Field label="موقع عمل السائق" error={errors.sectorId}>
            <select
              data-testid="vehicle-area"
              className={inputClass}
              value={form.sectorId}
              onChange={(e) => update('sectorId', e.target.value)}
            >
              <option value="">اختر المنطقة</option>
              {/* 00394: القطاعات من بيانات المناطق نفسها */}{parentCodesOf(areas).map((parent) => <optgroup key={parent} label={parentSectorTitle(parent)}>{areas.filter((a) => a.parentSector === parent).map((a) => <option key={a.id} value={a.id}>{a.name}</option>)}</optgroup>)}
            </select>
          </Field>
        </div>
        {create.isError && (
          <p className="mt-4 rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700">
            تعذر حفظ الآلية. تحقق من عدم تكرار DB أو اللوحة أو الشاصي.
          </p>
        )}
        <div className="mt-6 flex justify-end gap-3">
          <button type="button" onClick={onClose} className="h-11 rounded-xl border px-5 font-bold">
            إلغاء
          </button>
          <button
            data-testid="vehicle-submit"
            disabled={create.isPending}
            className="inline-flex h-11 items-center gap-2 rounded-xl bg-cyan-700 px-6 font-black text-white disabled:opacity-60"
          >
            <CarFront size={18} />
            {create.isPending ? 'جارٍ الحفظ…' : 'حفظ الآلية'}
          </button>
        </div>
      </form>
    </div>
  )
}
function Field({
  label,
  error,
  wide,
  optional,
  children,
}: {
  label: string
  error?: string
  wide?: boolean
  optional?: boolean
  children: React.ReactNode
}) {
  return (
    <label
      className={`space-y-1.5 text-xs font-bold text-slate-600 ${wide ? 'sm:col-span-2' : ''}`}
    >
      <span>
        {label}{' '}
        {optional ? (
          <small className="font-normal text-slate-400">(اختياري)</small>
        ) : (
          <b className="text-red-500">*</b>
        )}
      </span>
      {children}
      {error && <span className="block text-red-600">{error}</span>}
    </label>
  )
}
